<section class="tarjeta card-form usuarios-formulario" id="nuevo-usuario"><h2 class="tarjeta-titulo"><span class="formulario-icono" aria-hidden="true">+</span>Nuevo Usuario</h2><form method="POST" action="<?php echo URL_BASE; ?>usuarios/guardar" class="form-grid cliente-formulario"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars(csrf_token()); ?>"><div class="campo form-group"><label for="usuario-nombre">Nombre completo</label><input id="usuario-nombre" name="nombre" required></div><div class="campo form-group"><label for="usuario-username">Nombre de usuario</label><input id="usuario-username" name="username" required autocomplete="username"></div><div class="campo form-group"><label for="usuario-password">Contraseña</label><input id="usuario-password" name="password" type="password" minlength="6" required autocomplete="new-password"></div><div class="campo form-group"><label for="usuario-rol">Rol</label><select id="usuario-rol" name="rol"><option value="cajero">Cajero</option><option value="vendedor">Vendedor</option><option value="cajero_movil">Cajero Móvil (Celular / Tablet)</option><option value="admin">Administrador</option></select></div><div class="campo form-group"><label for="usuario-estado">Estado</label><select id="usuario-estado" name="estado"><option value="1">Activo</option><option value="0">Inactivo</option></select></div><div class="campo form-group"><label for="usuario-sucursal">Sucursal</label><input id="usuario-sucursal" name="sucursal" placeholder="Ej. Mi Negocio"></div><div class="campo form-group"><label for="usuario-caja">Caja asignada</label><select id="usuario-caja" name="caja_id"><option value="0">Sin caja asignada</option><?php foreach ($cajas as $caja): ?><option value="<?php echo (int)$caja['id']; ?>"><?php echo htmlspecialchars($caja['nombre']); ?></option><?php endforeach; ?></select></div><div class="form-acciones"><button class="btn btn-primario" type="submit">Guardar usuario</button></div></form></section>
<section class="tarjeta usuarios-lista"><h2 class="tarjeta-titulo">Usuarios registrados</h2><div class="tabla-responsive"><table class="tabla-catalogo"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Sucursal</th><th>Caja</th><th>Acciones</th></tr></thead><tbody><?php foreach ($usuarios as $usuario): ?><tr><td><strong><?php echo htmlspecialchars($usuario['nombre']); ?></strong></td><td><?php echo htmlspecialchars($usuario['usuario']); ?></td><td><?php echo $usuario['rol'] === 'admin' ? 'Administrador' : (in_array($usuario['rol'], ['vendedor', 'cajero_movil'], true) ? 'Vendedor' : 'Cajero'); ?></td><td><span class="estado-usuario <?php echo $usuario['estado'] ? 'activo' : 'inactivo'; ?>"><?php echo $usuario['estado'] ? 'Activo' : 'Inactivo'; ?></span></td><td><?php echo htmlspecialchars($usuario['sucursal'] ?? 'Sin asignar'); ?></td><td><?php echo htmlspecialchars($usuario['caja_nombre'] ?? 'Sin asignar'); ?></td><td><a class="btn btn-secondary" href="<?php echo URL_BASE; ?>usuarios/editar/<?php echo (int)$usuario['id']; ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></section>
